// filepath: lib/finance-toolkit/finance-toolkit.types.ts

/**
 * Finance Toolkit — shape of the static sample dataset generated by
 * data-prep/build-finance-toolkit-data.mjs from the Maconomy exports.
 *
 * Tables are stored as positional tuples to keep the file small; the
 * `FT_*` index constants below name each position. Read them through the
 * helpers in ./model.ts rather than indexing by hand.
 */

export type AgencyCurrency = "CAD" | "USD";

export interface FtAgency {
  id: string;
  name: string;
  /** Currency every amount of this agency is expressed in (hours cost and revenue). */
  currency: AgencyCurrency;
  /** False for an agency that has revenue but no hours export (K72). */
  hasHours: boolean;
}

/**
 * How a client's revenue was tied to its hours:
 * - `number`        exact Maconomy client number in the same agency
 * - `name`          exact match on the normalized name (case, accents, legal suffixes ignored)
 * - `none`          hours but no revenue line ("no revenue match")
 * - `revenue-only`  revenue but no hours in the same agency
 * - `internal`      an agency house account (time off, internal work) — overhead, not a client
 */
export type FtMatchStatus = "number" | "name" | "none" | "revenue-only" | "internal";

/** [agencyIndex, clientNumber, name, match, firstClientMonth, lastClientMonth] (−1 = none) */
export type FtClientTuple = [number, string, string, FtMatchStatus, number, number];

/**
 * Time class of an hour, from its Maconomy work code:
 * 0 client work · 1 internal (16xx: admin, training, new business…) · 2 time off (15xx).
 */
export type FtTimeClass = 0 | 1 | 2;

/**
 * [client, month, role, timeClass, hours, costBase1, costEnterprise, billed, costedHours]
 * costedHours = the hours whose Maconomy entry carries a cost amount; the rest
 * belong to employees with no cost rate on file.
 */
export type FtFactTuple = [number, number, number, FtTimeClass, number, number, number, number, number];

/** [client, revenueMonth, grossRevenue] */
export type FtRevenueTuple = [number, number, number];

/** [client, month, anonymous employee ids who logged client work that month] */
export type FtStaffTuple = [number, number, number[]];

export interface FinanceToolkitData {
  generatedAt: string;
  /** "YYYY-MM" for every month with hours, ascending. Fact month = index here. */
  months: string[];
  /** "YYYY-MM" covered by the gross revenue reports. Revenue month = index here. */
  revenueMonths: string[];
  agencies: FtAgency[];
  /** English role labels (Maconomy EmployeeCategoryName, French half dropped). */
  roles: string[];
  clients: FtClientTuple[];
  facts: FtFactTuple[];
  revenue: FtRevenueTuple[];
  staff: FtStaffTuple[];
  /** Media investment and complexity per Forecaster client (Staffing tab). Absent in older builds. */
  staffing?: FtStaffingData;
  source: {
    hoursRows: number;
    employees: number;
    hoursByBu: Record<string, { rows: number; hours: number; from: string; to: string }>;
    /** Median client-work hours per full employee-month (≥ 100 h logged). */
    fteMedianClientHours: number;
    /** Median total logged hours per full employee-month. */
    fteMedianTotalHours: number;
  };
}

export type CostBasis = "base1" | "enterprise";

// ─── Staffing (media investment + campaign complexity per Forecaster client) ──

/** [channel, spend CAD, share of that spend linked to MediaBox (0–1)] */
export type FtChannelSpendTuple = [string, number, number];

/** MediaBox complexity of a client's linked campaigns over the window. */
export interface FtComplexity {
  campaigns: number;
  tactics: number;
  publishers: number;
  audiences: number;
  markets: number;
  languages: number;
  linesOfBusiness: number;
  /** Funnel stages covered (upper, mid, lower/loyalty), from the objective field. */
  funnelStages: number;
  /** Share of tactics with a brand KPI (CPM, reach, completion…) vs performance. */
  brandKpiShare: number | null;
}

/**
 * Campaign complexity from PCC_Media_Investment.finance_master_mapping (the
 * table behind Reports › MediaBox Planner Data), per Adriana's proposed logic:
 * unique campaigns, then per-campaign averages. BigQuery:
 * Finance_Toolkit.staffing_campaign_complexity(from, to).
 */
export interface FtCampaignComplexity {
  /** Unique MediaBox campaigns with plan months in the window (v1 and v2). */
  campaigns: number;
  /** Of those, campaigns with a tactic whose billing ID is a MediaOcean MCPE. */
  campaignsMcpe: number;
  avgMediaTypes: number;
  avgPublishers: number;
  avgTactics: number;
  tactics: number;
}

/** One Forecaster client with MediaOcean spend in the staffing window. */
export interface FtStaffingClient {
  /** Forecaster client id (CL_ID). */
  id: string;
  name: string;
  agency: string;
  region: string;
  gmPod: string;
  /** Maconomy client numbers (Forecaster GAIA numbers): ties the spend to the hours. */
  gaia: string[];
  spend: number;
  digitalSpend: number;
  /** Spend scaled to a year for a client new in the window; equals spend otherwise. */
  annualizedSpend: number;
  isNew: boolean;
  /** "YYYY-MM" of the first month with spend in the window. */
  firstMonth: string | null;
  channels: FtChannelSpendTuple[];
  /** Spend CAD per month of `FtStaffingData.spendMonths` (every month of the hours data). */
  monthlySpend: number[];
  mcpeCount: number;
  estimateCount: number;
  vendorCount: number;
  /** Share of spend whose MCPE matches a MediaBox campaign (0–1). */
  mediaboxShare: number;
  /** Campaign complexity (finance_master_mapping): the measure used in the model. */
  campaignComplexity: FtCampaignComplexity | null;
  /** Extra planning details (mediabox_3.planning: audiences, markets, funnel), on MCPE-linked tactics. */
  complexity: FtComplexity | null;
}

/** Generated by data-prep/build-staffing-data.mjs from the Finance_Toolkit BigQuery functions. */
export interface FtStaffingData {
  generatedAt: string;
  /** "YYYY-MM" window, aligned with the last 12 months of the hours data. */
  from: string;
  to: string;
  /** "YYYY-MM" for `monthlySpend`: the same months as the hours data. */
  spendMonths: string[];
  clients: FtStaffingClient[];
  /** MediaOcean spend in the window on clients that are not in the Forecaster (left out). */
  spendNotInForecaster: number;
}
